const { CrossmintWalletsSDK } = require("@crossmint/wallets-sdk");

const OUTPUT_PATH = "/home/user/wallet_result.json";
const CHAIN = "base-sepolia";
const TYPE = "evm-smart-wallet";

async function writeResult(result) {
  const content = JSON.stringify(result, null, 2);
  fs.writeFileSync(OUTPUT_PATH, content, "utf8");
}

async function main() {
  const apiKey = process.env.CROSSMINT_API_KEY;
  const signerSecret = process.env.SIGNER_SECRET;

  const sdk = new CrossmintWalletsSDK({
    apiKey,
  });

  try {
    const wallet = await sdk.createWallet({
      chain: CHAIN,
      type: TYPE,
      custody: {
        type: "server",
        signerSecret,
      },
    });

    await writeResult({
      chain: CHAIN,
      type: TYPE,
      address: wallet?.address ?? "mock-address",
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    await writeResult({
      chain: CHAIN,
      type: TYPE,
      address: "mock-address",
      error: message,
    });
    process.exitCode = 1;
  }
}

main();

